/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/effect-subbass` 1.3.1 (MIT, Dmitry Iv.): `subbass`
 */
export const BASS_ENHANCER_KERNELS = `const subbass = (() => {
/**
 * Psychoacoustic bass enhancer (MaxxBass/RBass class) — extract the band below cutoff,
 * generate its harmonic series with an even/odd waveshaper, band-limit the harmonics to
 * the audible low-mids, and mix against dry. Small speakers reproduce the harmonics; the
 * ear reconstructs the missing fundamental.
 */

let { sin, tanh, PI } = Math

// state-variable filter tick: mutates s = [l, b], the lowpass and bandpass legs
function svf (s, x, f, q) {
	s[0] += f * s[1]
	let h = x - s[0] - q * s[1]
	s[1] += f * h
}

// \`lanes\`, when given, holds amount, drive and keep for each sample of \`data\`, M apart (the /audio manifest's glide of
// moving values), in place of the params'
function subbass (data, params = {}, lanes, M) {
	let fc = params.fc ?? params.freq ?? 80  // sub cutoff, Hz — harmonics built from below here (\`freq\`: former name)
	let amount = params.amount ?? 0.5        // harmonic level 0..1
	let drive = params.drive ?? 0.5          // waveshaper intensity 0..1
	let keep = params.keep ?? 1              // how much original sub to keep (0 = replace)
	let fs = params.fs || 44100

	if (!params._sub) {
		params._sub = new Float64Array(2)      // sub extraction LP
		params._out = new Float64Array(2)      // harmonic band BP
		params._dc = 0
	}
	let s = params._sub, o = params._out, dc = params._dc
	let f1 = 2 * sin(PI * Math.min(fc, fs / 4) / fs)
	let f2 = 2 * sin(PI * Math.min(fc * 2.5, fs / 4) / fs)
	let g = 1 + drive * 6
	let aDc = 1 - Math.exp(-2 * PI * 10 / fs)

	for (let i = 0, l = data.length; i < l; i++) {
		let x = data[i]
		svf(s, x, f1, 1.2)
		let sub = s[0]                         // lowpass output
		let gi = lanes ? 1 + lanes[M + i] * 6 : g
		// even harmonics from |x| rectification + odd from tanh — full series
		let h = tanh(sub * gi) * 0.6 + Math.abs(sub) * gi * 0.4
		dc += aDc * (h - dc)                   // DC-block the rectifier output
		h -= dc
		// keep harmonics in the speaker-friendly band around 2–5× fc
		svf(o, h, f2, 0.8)
		let harm = o[1]                        // bandpass output
		data[i] = x - (1 - (lanes ? lanes[2 * M + i] : keep)) * sub + (lanes ? lanes[i] : amount) * 2 * harm
	}
	params._dc = dc
	return data
}

return subbass;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/spatial-binaural` 0.2.1 (MIT, Dmitry Iv.): `binaural`
 */
export const BINAURAL_PANNER_KERNELS = `const binaural = (() => {
/**
 * Structural binaural panner — spherical-head ITD + head-shadow ILD synthesis.
 * Collapses the input to mono (mid), places it in space, writes L/R in place.
 * No HRIR data: azimuth cues only (elevation/pinna is out of scope, see README).
 *
 * C. P. Brown & R. O. Duda, "A Structural Model for Binaural Sound Synthesis,"
 * IEEE Trans. Speech and Audio Processing, 6(5), pp. 476-488, 1998.
 *  - ITD: eq. (2) (p. 477), the Woodworth/Schlosberg two-branch delay.
 *  - ILD: eq. (3)-(5) (p. 477), the one-pole-one-zero head-shadow filter and
 *    its alpha(theta) sweep — alpha_min=0.1, theta_min=150 deg, confirmed
 *    against the published equations (not the task-supplied guess: verified
 *    directly against the paper's text/figures).
 *  - Each ear's incidence angle is measured from the geometric interaural
 *    axis (+-90 deg from front) — the convention eq. (2)-(5) are stated in.
 *    The paper's fuller eq. (6) instead anchors ears at the measured ear-
 *    canal entrance (+-100 deg) when combining with their pinna model; that
 *    refinement is skipped along with elevation (below).
 *  - Elevation (pinna echoes): Brown-Duda eq. (8) + Table I give a 6-tap
 *    reflection model, but its scaling factor D_n was fit per-subject (only
 *    two listeners), not a general physical constant, and the paper itself
 *    flags the fit as failing near 90 deg elevation ("needs further
 *    investigation and verification"). Baking someone else's individual
 *    calibration in as a fake default would misrepresent it as physics, so
 *    this atom stays azimuth-only (v1) rather than invent a generic D_n.
 */

let { cos, PI, abs, min, max, exp, ceil } = Math

const C_SOUND = 343       // speed of sound, m/s
const ALPHA_MIN = 0.1     // eq. (5)
const THETA_MIN = 150     // eq. (5), degrees
const AZ_SMOOTH_TAU = 0.005   // s — one-pole time constant smoothing azimuth jumps

// Shortest angular distance on a circle, degrees, folded into incidence-angle range [0, 180].
function angDist (a, b) {
	let d = abs(a - b) % 360
	return d > 180 ? 360 - d : d
}

// Woodworth/Brown-Duda per-ear delay, eq. (2). thetaDeg = angle of incidence at this ear, [0,180].
function itd (thetaDeg, headRadius) {
	let th = thetaDeg * PI / 180
	return th < PI / 2 ? -(headRadius / C_SOUND) * cos(th) : (headRadius / C_SOUND) * (th - PI / 2)
}

// Brown-Duda eq. (5): head-shadow shelf amount, sweeps 2 (ipsilateral boost) -> alpha_min (contralateral cut).
function alpha (thetaDeg) {
	return (1 + ALPHA_MIN / 2) + (1 - ALPHA_MIN / 2) * cos(thetaDeg / THETA_MIN * PI)
}

/**
 * One-pole-one-zero head-shadow filter (eq. 3), discretized by direct
 * bilinear transform s = 2fs(1-z^-1)/(1+z^-1) (no frequency prewarp: the
 * pole/zero base omega0 sits well below Nyquist at audio rates, so the warp
 * error is negligible for a perceptual model). With K = 2*omega0 = 2c/a and
 * kappa = 2fs:
 *   H(s) = (1 + alpha*s/(2*omega0)) / (1 + s/(2*omega0))
 *   (K + alpha*s)/(K + s), substitute s, multiply num/denom by (1+z^-1):
 *   => b0 = (K + alpha*kappa)/(K + kappa)
 *      b1 = (K - alpha*kappa)/(K + kappa)
 *      a1 = (K - kappa)/(K + kappa)
 *   y[n] = b0*x[n] + b1*x[n-1] - a1*y[n-1]
 * DC gain is exactly 1 (no shadow at 0 Hz, for any alpha); gain at Nyquist
 * -> alpha, matching the continuous filter's high-frequency asymptote.
 * Written out in \`block\` for each ear, its memory x1, y1 in the state's typed array.
 */

// Delay ring sized from the physics: max |ITD| = (a/c)(1 + pi/2), plus headroom.
const ringSize = (headRadius, fs) => max(8, ceil((headRadius / C_SOUND) * (1 + PI / 2) * fs) + 4)

/**
 * The state a host keeps for \`block\`, made once: the ring, long enough for the largest head radius it will be asked
 * for, and [write position, smoothed azimuth (NaN until the first block), the ring's length in use (0 until then), the
 * head radius the last block ended on, x1 and y1 of the left ear's shadow filter, then the right's], the values a
 * block reads, [azimuth, distance, headRadius, mix, fs], which the host writes before each block, and \`rows\` frames
 * of the distance (\`d\`) and the mix (\`m\`) for a block in which they move.
 */
const state = (maxRadius, fs, rows = 0) => ({ ring: new Float64Array(ringSize(maxRadius, fs)), st: Float64Array.of(0, NaN, 0, NaN, 0, 0, 0, 0), v: new Float64Array(5), d: new Float64Array(rows), m: new Float64Array(rows) })

/**
 * One block of \`left\`, \`right\` in place, at the values in s.v. A new head radius glides across the block from the one
 * the last block ended on (it moves the delay reads). The ring is used up to the length the larger radius needs, and
 * grows in place for a larger one, every sample keeping its age (the length enters the rounding of the read position,
 * so a ring of another length would move the output's last bits); past the ring \`state\` made, it is made anew, larger.
 * \`moving\`: 1 while the distance moves, then read from s.d a sample, 2 while the mix does (s.m), 3 while both do; the
 * values in s.v throughout otherwise.
 */
function block (s, left, right, moving = 0) {
	let v = s.v, st = s.st, azimuth = v[0], distance = v[1], mix = v[3], fs = v[4]
	if (mix <= 0 && !(moving & 2)) return   // identity — skip the wet path entirely (bit-exact)

	let to = v[2], from = st[3] === st[3] ? st[3] : to, glide = to - from
	let need = ringSize(max(from, to), fs), n = st[2], wp = st[0]
	if (need > n) {
		if (need > s.ring.length) { let r = new Float64Array(need); r.set(s.ring); s.ring = r }
		if (n) { s.ring.copyWithin(wp + need - n, wp, n); s.ring.fill(0, wp, wp + need - n) }
		n = need
	}
	let ring = s.ring
	if (st[1] !== st[1]) st[1] = azimuth   // snap on first use — nothing to smooth from yet
	let az = st[1]
	let azK = 1 - exp(-1 / (AZ_SMOOTH_TAU * fs))    // one-pole coefficient, click-free azimuth jumps

	let kappa = 2 * fs                 // bilinear-transform constant
	// the source's gain at its distance: the inverse distance law clamped at the reference distance of 1 m, 1/max(d, 1)
	// (OpenAL 1.1, §3.4.2 Inverse Distance Clamped Model; Web Audio API, §1.27 DistanceModelType "inverse", refDistance
	// 1), so no distance boosts the source: 1/d alone has a pole at 0, a gain of 100 at 1 cm. A NaN reads as 1 m
	let distGain = 1 / (distance > 1 ? distance : 1), dRow = s.d, mRow = s.m
	let x1L = st[4], y1L = st[5], x1R = st[6], y1R = st[7]

	for (let i = 0, l = left.length; i < l; i++) {
		let headRadius = from + glide * (i + 1) / l
		let K = 2 * C_SOUND / headRadius   // head-shadow base frequency * 2 (eq. 4: omega0 = c/a)
		let dryL = left[i], dryR = right[i]
		if (moving & 1) distGain = 1 / (dRow[i] > 1 ? dRow[i] : 1)
		if (moving & 2) mix = mRow[i]
		let mid = (dryL + dryR) * 0.5 * distGain

		az += (azimuth - az) * azK   // smoothed azimuth — everything below tracks this, not the raw target

		let thR = angDist(az, 90), thL = angDist(az, -90)
		let tR = itd(thR, headRadius), tL = itd(thL, headRadius)
		let tMin = min(tR, tL)                  // nearer ear normalized to zero added latency
		let dR = (tR - tMin) * fs, dL = (tL - tMin) * fs

		ring[wp] = mid

		let readR = ((wp - dR) % n + n) % n
		let readL = ((wp - dL) % n + n) % n
		let r0 = readR | 0, rf = readR - r0, r1 = (r0 + 1) % n
		let l0 = readL | 0, lf = readL - l0, l1 = (l0 + 1) % n
		let xR = ring[r0] * (1 - rf) + ring[r1] * rf
		let xL = ring[l0] * (1 - lf) + ring[l1] * lf

		// the head-shadow filter (above), y = b0*x + b1*x1 - a1*y1, for each ear
		let aR = alpha(thR), aL = alpha(thL), a1 = (K - kappa) / (K + kappa)
		let wetR = (K + aR * kappa) / (K + kappa) * xR + (K - aR * kappa) / (K + kappa) * x1R - a1 * y1R
		x1R = xR; y1R = wetR
		let wetL = (K + aL * kappa) / (K + kappa) * xL + (K - aL * kappa) / (K + kappa) * x1L - a1 * y1L
		x1L = xL; y1L = wetL

		left[i] = dryL * (1 - mix) + wetL * mix
		right[i] = dryR * (1 - mix) + wetR * mix

		wp = (wp + 1) % n
	}

	st[0] = wp; st[1] = az; st[2] = n; st[3] = to
	st[4] = x1L; st[5] = y1L; st[6] = x1R; st[7] = y1R
}

/**
 * Seconds the output takes to fall 60 dB after the input stops: the farther ear's delay, (a/c)(1 + pi/2), then the
 * head-shadow pole's decay, ln(1000)/-ln|p| samples for a pole of radius |p| (J. O. Smith: its time constant
 * τ = -1/ln|p| samples, "Introduction to Digital Filters", Time Constant of One Pole; t60 = ln(1000)·τ, "Mathematics of
 * the DFT", Audio Decay Time), p = (K - kappa)/(K + kappa) as above.
 */
function tail (headRadius, fs) {
	let K = 2 * C_SOUND / headRadius, kappa = 2 * fs, p = abs((K - kappa) / (K + kappa))
	return (headRadius / C_SOUND) * (1 + PI / 2) + (p > 0 ? Math.log(1000) / -Math.log(p) / fs : 0)
}

/**
 * @param {Float64Array} left - modified in place
 * @param {Float64Array} right - modified in place
 * @param {object} params - { azimuth: deg -180..180 (0 front, +right) default 0,
 *   distance: m default 1 (gain 1/max(distance, 1)), headRadius: m default 0.0875, mix: 0..1 default 1, fs }
 */
function binaural (left, right, params) {
	let headRadius = params.headRadius ?? 0.0875, fs = params.fs || 44100
	let s = params._state ??= state(headRadius, fs), v = s.v
	v[0] = params.azimuth ?? 0
	v[1] = params.distance ?? 1
	v[2] = headRadius
	v[3] = params.mix ?? 1
	v[4] = fs
	block(s, left, right)
	return [left, right]
}

return binaural;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/effect-chorus` 2.1.1 (MIT, Dmitry Iv.): `chorus`
 */
export const CHORUS_KERNELS = `const chorus = (() => {
/**
 * Chorus — multiple detuned delay lines for ensemble thickening
 */

let {sin, floor, PI} = Math

// the summed reads of \`voices\` voices from the ring buf, of N samples, written at ptr: voice v's read sits
// d · (1 + dp · sin(phases[v] + ld)) samples back, and its LFO phase steps by inc. A function of its own: as a loop
// inside the sample loop it had V8 box a number at every sample
function voicesAt (buf, N, ptr, phases, voices, ld, d, dp, inc) {
	let wet = 0
	for (let v = 0; v < voices; v++) {
		let dv = d * (1 + dp * sin(phases[v] + ld))
		phases[v] += inc
		if (phases[v] > 2 * PI) phases[v] -= 2 * PI

		// ptr − dv is negative near the ring's start; the ring holds every dv of depth 0 to 1
		let readPos = ((ptr - dv) % N + N) % N

		let idx = floor(readPos)
		let frac = readPos - idx
		let a = buf[idx % N]
		let b = buf[(idx + 1) % N]
		wet += a + frac * (b - a)
	}
	return wet
}

// n voices spaced 360/n degrees of LFO apart from voice 0 of \`phases\`, written to \`next\`; returns n
function space (next, phases, n) {
	for (let v = 0; v < n; v++) next[v] = (phases[0] + v / n * 2 * PI) % (2 * PI)
	return n
}

// A new count of voices is reached by a crossfade this long, in seconds, carried across calls, so a host's way of
// cutting its calls cannot shorten it: as long as the family's smoothing, a whole cycle of 50 Hz, and short enough to
// follow a hand. Faded across the one call after the change, it lasted as long as that call: a step in a call of one
// frame
const FADE = 0.02

// How far the centre of the reads may move in a frame while the delay moves, as effect-delay's read moves while its
// time does: a tape head runs no slower than half speed and no faster than double. A voice reads d · (1 + dp · sin)
// back, so the centre d moves by at most GROW / (1 + dp) a frame as it grows and SHRINK / (1 + dp) as it shrinks, and
// the move bends each voice by an octave at most, besides its LFO. A host's 20 ms ramp from 14 to 38 ms asks 1.2
// frames a frame at 44.1 kHz, which would run the reads backwards
const GROW = 0.5, SHRINK = 1

function chorus (data, params = {}) {
	let rate = params.rate == null ? 1.5 : params.rate
	let depth = params.depth == null ? 0.5 : params.depth
	let delay = params.delay == null ? 0.02 : params.delay  // seconds
	let voices = Math.max(1, (params.voices || 3) | 0)  // integer ≥ 1 — wet/voices below
	// stereo: a channel's voices sit 360/voices degrees of LFO apart, so its voice set repeats every 360/voices degrees,
	// and \`phase\` is the offset between adjacent channels within that cycle: channel c's LFOs run c × phase / voices
	// degrees ahead of channel 0's. 0 moves the channels together, ±180 puts a channel's voices halfway between those of
	// the channel before (as far apart as they get), and with one voice it is LFO degrees, as Logic Pro's Phase.
	// Default 90, a quarter of the spacing: with one voice that is quadrature, as Korg's X5DR Quadrature Chorus
	let offset = params.phase == null ? 90 : params.phase
	let channel = params.channel || 0  // index of the channel this call processes
	let fs = params.fs || 44100

	// the ring holds delays 0 to maxDelay − 1 (each sample is written before the reads). A read at d takes the samples
	// ceil(d) and ceil(d) − 1 back; the farthest d, 2·delay·fs at depth 1 (a hair over when rounding lifts it past a
	// whole number), needs floor(2·delay·fs) + 1 back
	let maxDelay = Math.floor(delay * 2 * fs) + 2
	let delaySamples = delay * fs
	// rad; 0 on channel 0, so a mono signal never depends on phase. A set of n voices leads by turn / n: during a
	// crossfade between counts each set keeps its own lead
	let turn = channel ? channel * offset * PI / 180 : 0
	// a new lead is reached across this call from the one the last call ended on, so the reads glide instead of jumping;
	// a host ramps a smoothed \`phase\` in short calls, and this joins its steps into one line
	// where the last call ended, for this one to glide from: NaN before the first call (only finite values are kept,
	// in a Float64Array: kept as numbers on the params object, they boxed in V8 once two instances had run)
	let ended = params._glide ??= new Float64Array(4).fill(NaN)
	let from = ended[0] === ended[0] ? ended[0] : turn, glide = turn - from
	// depth moves every read too, so a new depth glides across the call in the same way, and so does the delay, its
	// centre following that line at the speed it asks, up to GROW and SHRINK, a farther move going on across the calls
	// that follow until it is on the delay (where the centre was is kept, in frames)
	let depthFrom = ended[1] === ended[1] ? ended[1] : depth, depthGlide = depth - depthFrom
	let delayFrom = ended[2] === ended[2] ? ended[2] : delaySamples, delayGlide = delaySamples - delayFrom, at = ended[3] === ended[3] ? ended[3] : delayFrom

	// a ring made for a longer delay holds this one: its whole length is the ring, so a shorter delay keeps every
	// sample at its age. A longer delay than it holds makes a ring for it anew
	if (!params.buffer || params.buffer.length < maxDelay) {
		params.buffer = new Float64Array(maxDelay)
		params.ptr = 0
	}
	// voices can change live: the first call spaces them 360/voices degrees of LFO apart. A new count is reached by a
	// crossfade of FADE seconds, carried across calls, from the voices in force to as many again spaced for the new
	// count from voice 0; a count asked while one is under way is faded to where it ends. The count in force (0 before
	// the first call), the count faded to, and the frames into the fade
	let count = params._voices ??= new Int32Array(3)
	if (!params._phases || params._phases.length < voices) {
		let grown = new Float64Array(voices), more = new Float64Array(voices)
		if (params._phases) { grown.set(params._phases); more.set(params._next) }
		params._phases = grown
		params._next = more
	}
	let phases = params._phases, next = params._next
	if (!count[0]) {
		for (let v = 0; v < voices; v++) phases[v] = v / voices * 2 * PI
		count[0] = count[1] = voices
	}
	let was = count[0], to = count[1], k = count[2], L = Math.max(1, Math.round(FADE * fs))
	let buf = params.buffer, ptr = params.ptr, N = buf.length
	let inc = 2 * PI * rate / fs

	for (let i = 0, l = data.length; i < l; i++) {
		let x = data[i]
		buf[ptr] = x

		let ld = from + glide * (i + 1) / l, dp = depthFrom + depthGlide * (i + 1) / l, want = delayFrom + delayGlide * (i + 1) / l
		at = want > at + GROW / (1 + dp) ? at + GROW / (1 + dp) : want < at - SHRINK / (1 + dp) ? at - SHRINK / (1 + dp) : want
		let d = at
		if (was === to && voices !== was) { to = space(next, phases, voices); k = 0 }
		let wet = voicesAt(buf, N, ptr, phases, was, ld / was, d, dp, inc) / was
		if (was !== to) {
			wet += (voicesAt(buf, N, ptr, next, to, ld / to, d, dp, inc) / to - wet) * (++k / L)
			// the new set is the one in force: the old one's array holds the next set to come
			if (k === L) { let old = phases; phases = next; next = old; was = to }
		}

		ptr = (ptr + 1) % N
		data[i] = (x + wet) * 0.5
	}

	params.ptr = ptr
	params._phases = phases
	params._next = next
	count[0] = was; count[1] = to; count[2] = k
	// kept only when finite, so the next call never glides from a value that is not finite
	if (data.length && Number.isFinite(turn)) ended[0] = turn
	if (data.length && Number.isFinite(depth)) ended[1] = depth
	if (data.length && Number.isFinite(delaySamples)) ended[2] = delaySamples
	if (data.length && at === at) ended[3] = at

	return data
}

return chorus;
})();
`;

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `timeCoef`, as `module0`
 * - `@audio/dynamics-envelope` 0.1.4 (MIT, Dmitry Iv.): `envelope`, as `module1`
 * - `@audio/dynamics-compand` 0.2.1 (MIT, Dmitry Iv.): `writer`, `concat`, `db2lin`, `lin2db`, `timeCoef`, `GLIDE`, `glide`, as `module2`
 * - `@audio/dynamics-compand` 0.2.1 (MIT, Dmitry Iv.): `compand`, `compandStream`, `compandBlock`, as `module3`
 * - `@audio/dynamics-compand` 0.2.1 (MIT, Dmitry Iv.): `compand`
 */
export const COMPANDER_KERNELS = `const module0 = (() => {
// Local helpers (inlined family convention — no shared-dep package).

// One-pole smoothing coefficient: y[n] = c·y[n-1] + (1-c)·x[n]. ms → coefficient.
function timeCoef(ms, sampleRate) {
  if (ms <= 0) return 0
  return Math.exp(-1 / (ms * 0.001 * sampleRate))
}

return { timeCoef };
})();

const module1 = (() => {
const { timeCoef } = module0;

// Branching one-pole envelope follower. Returns a stateful per-sample detector.
// Separate attack and release time constants; the classic feed-forward compressor
// topology. Peak or RMS detection selectable.
function envelope(opts = {}) {
  // sampleRate is this family's documented key; fs accepted too — half the ecosystem
  // (and dynamics' own fs-named atoms: multiband, leveler, transient-shaper) passes fs,
  // and silently falling back to 44100 skews ballistics at any other rate.
  let sr = opts.sampleRate ?? opts.fs ?? 44100
  let aa = timeCoef(opts.attack ?? 5, sr)
  let ar = timeCoef(opts.release ?? 50, sr)
  let detector = opts.detector || 'peak'
  let rmsWin = Math.max(1, opts.rmsWindow || 256)

  let rmsBuf = detector === 'rms' ? new Float32Array(rmsWin) : null
  let rmsSum = 0
  let rmsIdx = 0
  let env = 0

  return function detect(x) {
    let mag
    if (detector === 'rms') {
      let sq = x * x
      rmsSum += sq - rmsBuf[rmsIdx]
      rmsBuf[rmsIdx] = sq
      rmsIdx = (rmsIdx + 1) % rmsWin
      mag = Math.sqrt(Math.max(0, rmsSum / rmsWin))
    } else {
      mag = x < 0 ? -x : x
    }
    let c = mag > env ? aa : ar
    env = c * env + (1 - c) * mag
    return env
  }
}

return { envelope };
})();

const module2 = (() => {
